def rec(p):b=p.read_bytes();return {'path':str(p.relative_to(R))if p.is_relative_to(R)else str(p),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
def put(n,x):p=O/n;assert not p.exists();p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n');return rec(p)
def add(pre,td,te,ca,cb,qs,answers,criteria,essential):
 g=next(g for g in can['goals']if g['id'].startswith(pre));gid=g['id'];mid=str(uuid.uuid5(uuid.NAMESPACE_URL,'skillpilot:economics:20261010:local-full-contract:'+gid));phase=g.get('dimensionTags',{}).get('phase','E');phase=phase if phase in['E','Q1','Q2','Q3','Q4']else'Katalog';assert len(qs)==len(answers)==len(criteria)==6
 caps=('Bewertung: maximal 24 BE, bestanden ab 15 BE. Jede Aufgabe enthält zwei erläuterte Kriterien zu je 2 BE. Je Kriterium: 2 BE für fachlich tragfähige fallbezogene Leistung, 1 BE für einen nachvollziehbaren richtigen Teil, 0 BE bei fehlender oder falscher Leistung. Gleichwertige Darstellungen und begründete alternative Urteile zählen. Fachlich passende Leistungen werden in der gesamten Arbeit berücksichtigt, auch an anderer Stelle. Einzelne Rechen-, Sprach- oder Detailfehler, fehlende Bezeichnungen und nachvollziehbar unvollständige Ausführungen lösen keine Obergrenze aus. Ist jedoch in der gesamten Arbeit eine der folgenden wesentlichen Leistungen vollständig abwesend oder durchgehend fachlich falsch, wird die Gesamtpunktzahl auf höchstens 14 BE begrenzt: '+essential[0]+'. Es gibt keine Vollpunktpflicht, Musterwortpflicht oder Pflicht, jedes Detail jedes Falls ideal zu erfüllen.',
 'Scoring: maximum 24 marks, pass at 15. Each task has two explained criteria worth 2 marks each. Each criterion receives 2 for a defensible case-based performance, 1 for a meaningful correct part, and 0 for missing or incorrect work. Equivalent representations and reasoned alternative judgements count. Relevant evidence counts anywhere in the complete submission. Individual calculation, language or detail errors, omitted labels and defensible incomplete accounts do not trigger a cap. However, if any of the following essential performances is wholly absent or consistently wrong throughout the complete submission, cap the total at 14: '+essential[1]+'. Full marks, model wording and ideal completion of every detail in every case are not required.')
 intro=('Alle Personen, Beträge, Beiträge und Vergleichsdaten sind eigene fiktive Unterrichtsmaterialien. Es werden weder private Informationen erhoben noch echte Personen kontaktiert. Bearbeiten Sie beide unterschiedlichen Fälle eigenständig; Ergebnisse und Simulationen sind keine beobachteten Lernendenleistungen oder reale Erprobung.',
 'All people, amounts, contributions and comparison data are original fictional teaching materials. No private information is collected and no real person is contacted. Work independently on both different cases; calculations and simulations are not observed learner performance or real-world trials.')
 task='\n\n'.join([intro[0],'Fall A: '+ca[0],'Fall B: '+cb[0]]+[f'{i+1}. '+q[0]+' (4 BE)'for i,q in enumerate(qs)]+[caps[0]]);taskEn='\n\n'.join([intro[1],'Case A: '+ca[1],'Case B: '+cb[1]]+[f'{i+1}. '+q[1]+' (4 marks)'for i,q in enumerate(qs)]+[caps[1]])
 solution='\n\n'.join([f'{i+1}. '+a[0]for i,a in enumerate(answers)]+[caps[0]]);solutionEn='\n\n'.join([f'{i+1}. '+a[1]for i,a in enumerate(answers)]+[caps[1]])
 steps=[{'id':f's{i+1}','maxPoints':4,'description':k[0]+' Je Kriterium 2/1/0 BE nach der veröffentlichten Teilbewertung.','descriptionEn':k[1]+' Each criterion receives 2/1/0 under the published partial-credit rule.'}for i,k in enumerate(criteria)]
 m={'id':mid,'title':td,'titleEn':te,'description':'Die lernende Person kann zwei unterschiedliche fiktive Fälle zum Thema „'+g['title']+'“ mit eigenen fachlich begründeten Ergebnissen und ausgewiesenen Grenzen bearbeiten.','descriptionEn':'The learner can address two different fictional cases concerning “'+g.get('titleEn',g['title'])+'” through their own reasoned results and explicit limits.','weight':1,'tags':['GK','LK','Practice','Assessment'],'contains':[],'requires':[gid],'type':'atomic','phase':phase,'dimensionTags':{'framework':'canonical-gymnasium-economics','demandLevel':'AB3','phase':phase},'extendedData':{'applicabilityFromRequires':True},'examData':{'reviewStatus':'draft','coveredGoalIds':[gid],'coveredStrands':['WW_WIRTSCHAFT'],'demandLevels':['AB1','AB2','AB3'],'taskContent':task,'taskContentEn':taskEn,'solutionContent':solution,'solutionContentEn':solutionEn,'scoring':{'maxPoints':24,'passingScore':15,'steps':steps}}};materials.append(m);specs.append({'materialId':mid,'coveredGoalId':gid,'actualPhase':phase,'wholeEssentialGroups':{'de':essential[0],'en':essential[1]},'actualSixTaskModelAnswers':answers,'actualSixRubricCriteria':criteria,'wholeCurrentGoal':g,'wholeOriginalP':pm[gid]})
add('eef95305','Konsum: Ausgangsoption, Darstellung und Anker unterscheiden','Consumption: distinguish defaults, frames and anchors',
('Zwei gleichwertige Musikangebote liefern 30 Tage dieselbe Leistung für 30 €. A bleibt nach einem Probemonat voreingestellt, B verlangt aktive Wahl; Wechsel dauert bei beiden einen Klick. Eine zweite Anzeige nennt denselben Gesamtpreis als 1 € je Tag, ausdrücklich für genau 30 Tage. Keine anderen Leistungsunterschiede sind gegeben.','Two equal music offers provide the same 30-day service for EUR30. A remains selected after a trial; B requires active choice. Switching takes one click in either case. Another advertisement states EUR1 per day, expressly for exactly 30 days. No other service differences are supplied.'),
('Ein identischer Rucksack kostet in beiden Anzeigen 48 €. Nur Anzeige X beginnt mit „früher 120 €“; dieser frühere Preis ist nicht belegt. Eine Vergleichsgruppe sieht X, eine andere dieselbe Anzeige ohne Vergleichspreis; Zuordnung ist zufällig und alle übrigen Angaben sind gleich. Häufigkeit eines Kaufes ist noch unbekannt.','The same backpack costs EUR48 in both advertisements. Only X begins with “previously EUR120”; that former price is unverified. Randomly assigned comparison groups see X or the otherwise identical advertisement without the reference price. Purchase frequency is not yet known.'),
[('A1: Ordnen und erklären Sie den Ausgangsoptionseffekt am Musikangebot.','A1: Classify and explain the initial-option effect in the music offer.'),('A2: Prüfen Sie die Preisdarstellung rechnerisch und erklären Sie ihren möglichen Einfluss.','A2: Check the price presentation numerically and explain its possible influence.'),('A3: Entwerfen Sie einen passenden Vergleich für beide Effekte und nennen Sie eine Erklärung, die der Fall nicht beweist.','A3: Design an appropriate comparison for both effects and identify an explanation not established by the facts.'),('B1: Erklären Sie den Bezugspunkteffekt, ohne den früheren Preis als Tatsache zu übernehmen.','B1: Explain the reference-point effect without treating the former price as established.'),('B2: Beurteilen Sie das Vergleichsdesign und welche zusätzlichen Ergebnisdaten nötig wären.','B2: Assess the comparison design and the additional outcome data needed.'),('B3: Unterscheiden Sie Ausgangsoption, Framing und Anker an den Fallmerkmalen; prüfen Sie „Jeder Kauf beweist einen Bias“.','B3: Distinguish defaults, framing and anchors by the case features; assess “Every purchase proves a bias”.')],
[('Das Beibehalten einer vorhandenen Standardoption kann Status-quo-Verhalten darstellen. Der Vergleich muss sonst gleiche Leistung und Wechselmöglichkeiten festhalten; eine bewusste Vorliebe bleibt möglich.','Retaining an existing default can exhibit status-quo behaviour. Compare equal service and switching opportunities; deliberate preference remains possible.'),('1×30=30 €. Gleicher Zeitraum und Leistung sind entscheidend; die kleinere Tageszahl kann den Preis anders rahmen, obwohl kein Kostenvorteil entsteht.','1×30=EUR30. Equal duration and service matter; a smaller daily number can frame the price differently without creating a cost advantage.'),('Zufällig gleiche Angebote mit/ohne Voreinstellung bzw. Tagesdarstellung zeigen, ob nur dieser Faktor mit dem Ergebnis variiert. Einzelne Vorlieben und echte Leistungsunterschiede wären alternative Erklärungen; ein tatsächlicher Effekt ist noch nicht gemessen.','Randomly vary only the default or daily presentation in otherwise equal offers. Individual preferences and actual service differences are alternatives; an effect has not yet been measured.'),('120 € kann die Bewertung von 48 € als günstig verankern. Das ist eine prüfbare Wirkungshypothese; die Behauptung zum Altpreis ist kein belegter Wert und ändert den Endpreis nicht.','EUR120 can anchor the assessment of EUR48 as cheap. This is a testable hypothesis; the former price is unverified and does not change the final price.'),('Gleicher Rucksack, Endpreis und zufällige Zuordnung isolieren den präsentierten Bezugspunkt. Man benötigt Kaufanteile oder vergleichbare Bewertungsdaten und Angaben zur Durchführung, bevor eine Gruppenwirkung behauptet wird.','Equal product, final price and random assignment isolate the displayed reference point. Purchase shares or comparable ratings and execution details are needed before claiming a group effect.'),('Voreinstellung betrifft eine Ausgangsoption; Tages-/Gesamtpreis ein gleichwertiges Framing; 120 € einen Anker. Ein Kauf kann Bedarf ausdrücken. Ein Bias wird durch den passenden Vergleich gestützt, nicht durch ein Schlagwort oder individuelles Motivlesen.','A default concerns an initial option, daily/total pricing an equivalent frame, and EUR120 an anchor. Buying can express need. A suitable comparison supports a bias explanation; labels or mind-reading do not.')],
[('K1: konkrete Ausgangsoption; K2: begründeter möglicher Mechanismus.','K1: specific initial option; K2: reasoned possible mechanism.'),('K1: gleiche 30-€-Kosten und Zeitraum; K2: mögliche Darstellungswirkung.','K1: equal EUR30 cost and period; K2: possible framing effect.'),('K1: kontrollierter Vergleich; K2: unbelegte Wirkung/alternative Erklärung.','K1: controlled comparison; K2: unproven effect/alternative explanation.'),('K1: fallbezogener Anker; K2: Altpreis-/Wirkungsgrenze.','K1: case-based anchor; K2: former-price/effect limit.'),('K1: Designbegründung; K2: passende erforderliche Ergebnisdaten.','K1: design justification; K2: appropriate outcome data.'),('K1: drei Mechanismen aus Merkmalen getrennt; K2: nichtpsychologisierende Belegprüfung.','K1: three mechanisms distinguished by features; K2: evidence without mind-reading.')],
('fallbezogene Unterscheidung der Ausgangsoption und äquivalenten Darstellung; Erklärung des Ankers; geeigneter Vergleich bei unveränderter Leistung und tatsächlichen Kosten','case-based distinction between initial option and equivalent framing; explanation of the anchor; an appropriate comparison holding service and actual costs fixed'))
add('84955a75','Konsumverhalten: Vergleich statt Motivbehauptung','Consumption behaviour: comparison rather than assumed motives',
('Eine Wetter-App kostet in beiden Varianten 4 € je Monat mit identischem Umfang. Bei zufällig zugeteilten 100 Personen pro Gruppe verlängert Variante D automatisch, Variante O nur durch aktive Wahl. Kündigung/Verlängerung benötigen denselben Klick. Nach einem Monat behalten 70 in D und 40 in O die App. Die Zahlen sind fiktiv.','A weather app costs EUR4 monthly with equal service. Randomly assigned groups of 100 see automatic renewal D or active renewal O. Cancelling/renewing each takes one click. After a month, 70 in D and 40 in O retain the app. These numbers are fictional.'),
('Dieselbe Lampe kostet 36 €. Gruppe X sieht zuerst „Vergleichspreis 90 €“, Gruppe Y nur 36 €; sonst identische Anzeigen. Fiktive mittlere Preisbewertungen auf gleicher Skala: X 8, Y 5. Der angebliche Vergleichspreis ist unbelegt, tatsächliche Käufe und persönliche Gründe wurden nicht gemessen.','The same lamp costs EUR36. X first sees “reference price EUR90”, Y only EUR36; all other advertising is equal. Fictional mean value ratings on the same scale are 8 and 5. The reference price is unverified; actual purchases and personal reasons were not measured.'),
[('A1: Berechnen Sie die Beibehaltungsanteile und den Unterschied; erklären Sie den möglichen Standardeffekt.','A1: Calculate retention shares and their difference; explain the possible default effect.'),('A2: Nennen Sie, was der Vergleich konstant hält und welche alternative Erklärung bei verändertem Leistungsumfang entstünde.','A2: Identify what is held fixed and the alternative explanation arising if service differed.'),('A3: Beurteilen Sie, was über die 70 einzelnen Personen ausgesagt werden darf.','A3: Assess what can be said about the 70 individuals.'),('B1: Erklären Sie einen möglichen Referenzpunkteffekt anhand der Bewertungsdifferenz.','B1: Explain a possible reference-point effect using the rating difference.'),('B2: Entwerfen Sie eine Prüfung, die Darstellung von echter Qualität trennt.','B2: Design a test separating presentation from actual quality.'),('B3: Grenzen Sie plausible Gruppenerklärung, bewiesene Kaufwirkung und individuelle Vorliebe ab.','B3: Distinguish a plausible group explanation, established purchase effects and individual preferences.')],
[('70% gegenüber 40%, also 30 Prozentpunkte. Die Voreinstellung kann Beibehaltung über Aufmerksamkeit, Bequemlichkeit oder Ausgangsoption beeinflussen.','70% versus 40%, a difference of 30 percentage points. Defaults may affect retention through attention, convenience or the initial option.'),('Preis, Umfang, Zeitraum, Gruppenzuteilung und Klickaufwand sind gleich. Eine bessere Leistung in D wäre eine andere Ursache und würde den reinen Darstellungsvergleich stören.','Price, service, period, assignment and click effort are equal. Better service in D would be another cause and confound a presentation-only comparison.'),('Der Gruppenunterschied stützt eine Verhaltenserklärung unter den Angaben. Nicht jede einzelne Verlängerung ist unbewusst; Bedürfnisse und Präferenzen können bestehen. Die fiktive Gruppe beweist keine allgemeine Häufigkeit.','The group difference supports a behavioural explanation under these facts. Not every renewal is unconscious; needs and preferences may matter. The fictional group establishes no universal frequency.'),('Die vorgestellten 90 € können die Bewertung der unveränderten 36 € verschieben; 8−5=3 Skalenpunkte. Der Bezugspreis bleibt unbelegt und die Skala ist keine Geldersparnis.','The displayed EUR90 can shift evaluation of the unchanged EUR36; 8−5=3 scale points. The reference price is unverified and the scale is not money saved.'),('Gleiche Lampe/Preis/Information bei zufälliger Variation nur des Bezugspreises; identische Bewertungsfrage und Kaufbeobachtung ergänzen. Qualitätsunterschiede würden eine separate Wirkung darstellen.','Hold lamp, price and information fixed and randomly vary only the reference price; use the same rating question and additionally observe purchases. Quality differences would be separate effects.'),('Eine Bewertungsdifferenz ist keine gemessene Kaufdifferenz. Eine passende Gruppenvariation stützt die Hypothese, identifiziert aber keine sicheren Motive einzelner Personen. Ein Kauf ohne Anker kann bewusster Bedarf sein.','A rating difference is not a measured purchase difference. A suitable group variation supports the hypothesis without establishing individuals’ motives. Buying without an anchor can reflect deliberate need.')],
[('K1: richtige Anteile/Prozentpunkte; K2: begründeter Standardeffekt.','K1: correct shares/percentage points; K2: reasoned default effect.'),('K1: Konstanten; K2: echte alternative Erklärung.','K1: fixed factors; K2: a genuine alternative explanation.'),('K1: Gruppe/Person getrennt; K2: Reichweitengrenze.','K1: group/individual distinction; K2: limit on generalisation.'),('K1: Bezugspunktmechanismus; K2: passende Skalen-/Altpreisgrenze.','K1: reference-point mechanism; K2: scale/former-price limit.'),('K1: isolierte Darstellung; K2: passende Ergebnisprüfung.','K1: isolated presentation; K2: appropriate outcome test.'),('K1: Bewertung versus Kaufwirkung; K2: Präferenzen und individuelle Ungewissheit.','K1: ratings versus purchase effects; K2: preferences and individual uncertainty.')],
('konkreter Verhaltenseffekt mit genanntem verändertem Einflussfaktor; geeigneter sonst gleicher Vergleich; Abgrenzung zu echten Leistungs-/Präferenzunterschieden','a specific behavioural effect with the changed factor identified; a suitable otherwise equal comparison; distinction from actual service/preference differences'))
add('a60e0541','Knappe Mittel: Bedarf, Nutzung und Werbereiz abwägen','Scarce means: weigh need, use and advertising',
('Ein fiktives Profil benötigt ein verkehrstaugliches Fahrrad für den täglichen Weg. Budget 75 €. Reparatur 45 € ermöglicht laut eigener Modellannahme voraussichtlich ein weiteres Nutzungsjahr; weiteres Versagen bleibt möglich. Beworbenes Zubehör kostet 60 € und beseitigt den Defekt nicht. Reparatur und Zubehör zusammen kosten 105 €. Werbung hebt „nur heute“ und Zugehörigkeit hervor. Keine gemessenen Umweltbilanzen liegen vor.','A fictional profile needs a roadworthy bicycle for daily travel. Budget EUR75. Repair at EUR45 is assumed likely to permit another year, but further failure is possible. Advertised accessories cost EUR60 and do not fix the defect. Both cost EUR105. Advertising emphasises “today only” and belonging. No measured environmental footprint is supplied.'),
('Eine fiktive Person hat 90 € verfügbar und braucht eine Tasche. X kostet 30 € und hält im gegebenen Erwartungsmodell ein Jahr; Y kostet 80 €, ist reparierbar und hält erwartet vier Jahre. Reparaturkosten sind nicht beziffert, tatsächliche Haltbarkeit und Umweltangaben unsicher. Ein Countdown bewirbt X. Die Person möchte Ausgaben begrenzen, aber auch wenig Material verbrauchen.','A fictional person has EUR90 and needs a bag. X costs EUR30 and lasts an expected year in the supplied model. Y costs EUR80, is repairable and lasts an expected four years. Repair costs are unspecified; actual lifetime and environmental statements are uncertain. A countdown promotes X. The person wants low spending and low material use.'),
[('A1: Prüfen Sie Bedarf, Budget und entgangene Alternativen; begründen Sie eine Wahl.','A1: Examine need, budget and foregone alternatives; justify a choice.'),('A2: Verbinden Sie eigene Anreize und Nachhaltigkeitsüberlegungen mit den gegebenen Grenzen.','A2: Connect personal incentives and sustainability considerations to the supplied limits.'),('A3: Erklären Sie den konkreten Werbe-/Verhaltenseinfluss und prüfen Sie die Wahl ohne Zeitdruck.','A3: Explain the specific advertising/behavioural influence and reconsider without time pressure.'),('B1: Vergleichen Sie Anschaffungsbudget und erwartete jährliche Nutzungskosten.','B1: Compare upfront affordability and expected annual use cost.'),('B2: Gewichten Sie persönliche und ökologische Gründe ergebnisoffen; benennen Sie fehlende Angaben.','B2: Weigh personal and environmental reasons openly; identify missing facts.'),('B3: Formulieren Sie eine begründete Entscheidung bei neutraler Darstellung und erläutern Sie die Rolle des Countdowns.','B3: Give a reasoned choice under neutral presentation and explain the countdown’s role.')],
[('Beide Einzeloptionen sind bezahlbar, zusammen nicht. Reparatur lässt 30 €, Zubehör 15 €; nur die Reparatur erfüllt den Wegbedarf. Der Verzicht auf Zubehör und sonstige Nutzung der 45 € ist als Opportunitätsabwägung zu begründen.','Each option is affordable but not both. Repair leaves EUR30, accessories EUR15; only repair meets transport need. Foregoing accessories and other uses of EUR45 should be justified as opportunity-cost reasoning.'),('Zuverlässige Mobilität und Erhalt vorhandener Materialien sprechen bedingt für Reparatur. Zugehörigkeit kann ein eigener Anreiz sein. Keine Garantie oder genaue Ökobilanz wird aus Preis oder Reparatur automatisch abgeleitet.','Reliable mobility and retaining materials conditionally favour repair. Belonging can be a personal incentive. Neither guaranteed reliability nor an exact footprint follows automatically from price or repair.'),('Dringlichkeit und sozialer Werbereiz können Aufmerksamkeit auf Zubehör lenken. Neutraler Vergleich nach Bedarf/Budget kann die Reparatur stärken; eine begründete andere Gewichtung muss trotzdem den Mobilitätsbedarf lösen.','Urgency and social cues can direct attention to accessories. Neutral comparison by need/budget can strengthen repair; a different defensible weighting must still address mobility.'),('30/1=30 € pro erwartetem Jahr, 80/4=20 €, ohne weitere Reparaturkosten. Beide passen anfangs in 90 €, aber Y bindet 80 € sofort. Erwartete Jahreskosten sind keine garantierten Zahlungen oder Haltbarkeiten.','30/1=EUR30 per expected year, 80/4=EUR20, excluding further repair costs. Both fit EUR90 upfront, but Y ties up EUR80 immediately. Expected annual cost is not guaranteed spending or lifetime.'),('Y kann weniger Ersatzbedarf bedeuten; X belässt zunächst mehr Liquidität. Reale Reparaturkosten, Materialfolgen und Haltbarkeit fehlen. Gewichtungen sind ausdrücklich am Bedarf und Budget zu begründen, nicht moralisch aus dem Produkt abzulesen.','Y can reduce replacement needs; X preserves more initial liquidity. Actual repair costs, material impacts and durability are missing. Weights should follow needs/budget rather than assigning moral merit by product.'),('Eine mögliche Wahl ist Y wegen erwarteter Nutzung, sofern 80 € tragbar bleiben; X kann bei dringendem sonstigem Bedarf begründet sein. Countdown ist kein neuer Qualitätsbeleg. Die neutral begründete Wahl zeigt bewusste Reflexion statt erzwungener Nachhaltigkeitsantwort.','Y is a possible choice for expected use if EUR80 remains feasible; X may be justified by other urgent needs. A countdown is no quality evidence. A neutral justification demonstrates reflection rather than a prescribed sustainability answer.')],
[('K1: Bedarf/Budget konsistent; K2: Wahl und Opportunitätsabwägung.','K1: consistent need/budget; K2: choice and opportunity-cost reasoning.'),('K1: eigene Anreize; K2: Nachhaltigkeit mit Evidenzgrenzen.','K1: personal incentives; K2: sustainability with evidence limits.'),('K1: konkreter Werbemechanismus; K2: neutraler begründeter Vergleich.','K1: specific advertising mechanism; K2: reasoned neutral comparison.'),('K1: Anschaffungsbudget; K2: erwartete Nutzungskosten mit Grenzen.','K1: upfront budget; K2: expected use cost with limits.'),('K1: offengelegte Gewichtung; K2: passende fehlende Angaben.','K1: explicit weighting; K2: relevant missing facts.'),('K1: reflektiertes bedingtes Urteil; K2: Darstellungseinfluss geprüft.','K1: reflective conditional judgement; K2: presentation effect examined.')],
('budget- und bedarfsbezogene Wahlbegründung; eigene Anreize und Nachhaltigkeitsfolgen mit Grenzen; konkreter Werbe-/Verhaltenseinfluss und Prüfung bei neutraler Darstellung','a choice justified by budget and need; personal incentives and sustainability consequences with limits; a specific advertising/behavioural influence and reconsideration under neutral presentation'))
add('e5b070d2','Haushaltsbudget: zwei eigene Tabellen mit Rücklage und Veränderung','Household budget: two own spreadsheets with reserves and input changes',
('Eine fiktive Monatsplanung erwartet 240 € Einnahmen, 90 € feste Ausgaben und 100 € variable Ausgaben; monatliches Sparziel 35 €. Erstellen Sie eine eigene Tabelle mit Eingabezellen und Zellbezugsformeln. Verändern Sie anschließend nur die variable Eingabe auf 115 €.','A fictional monthly plan expects EUR240 income, EUR90 fixed and EUR100 variable expenses, with EUR35 monthly saving. Create an original spreadsheet with input cells and cell-reference formulas. Then change only the variable input to EUR115.'),
('Ein anderer fiktiver Haushalt erwartet monatlich 360 € Einnahmen, 170 € feste und 110 € variable Ausgaben. Eine Jahreszahlung von 180 € soll durch Monatsrücklagen finanziert werden, daneben 50 € monatliches Sparziel. Erstellen Sie unabhängig eine zweite Tabelle, ändern Sie dann die Jahreseingabe auf 300 €. Fälligkeit und vorhandener Rücklagenbestand sind nicht bekannt.','Another fictional household expects monthly income EUR360, fixed expenses EUR170 and variable EUR110. An annual EUR180 charge is to be funded by monthly reserves, alongside EUR50 monthly saving. Independently create a second spreadsheet and then change the annual input to EUR300. Due date and existing reserve stock are unknown.'),
[('A1: Erstellen und übermitteln Sie die tatsächliche Tabelle; zeigen Sie Eingaben, Ausgabensumme und Restformel.','A1: Create and submit the actual spreadsheet; show inputs, expense sum and remainder formula.'),('A2: Ändern Sie die Eingabe und erläutern Sie die automatisch aktualisierten Werte.','A2: Change the input and explain the automatically updated values.'),('A3: Beurteilen Sie die Sparplanung und eine mögliche Anpassung mit Unsicherheitsgrenze.','A3: Assess the saving plan and a possible adjustment with uncertainty limits.'),('B1: Erstellen und übermitteln Sie eine unabhängige Monatsplanung mit Formel für die Jahresrücklage.','B1: Create and submit an independent monthly plan with a formula for the annual reserve.'),('B2: Führen Sie die 300-€-Eingabeänderung tatsächlich aus und erklären Sie Rücklage und Rest.','B2: Actually make the EUR300 input change and explain reserve and remainder.'),('B3: Unterscheiden Sie Rücklagenbildung, Zahlung und Liquidität am Fälligkeitstermin.','B3: Distinguish reserve accumulation, payment and liquidity at the due date.')],
[('Beispiel B2=240,B3=90,B4=100,B5=35; B6=SUM(B3:B4), B7=B2-B6-B5. Ausgaben 190 €, Rest 15 €. Andere richtige Zellstrukturen zählen; fest eingetragene Ergebnisse ersetzen Formeln nicht.','For example B2=240,B3=90,B4=100,B5=35; B6=SUM(B3:B4), B7=B2-B6-B5. Expenses EUR190, remainder EUR15. Other correct cell structures count; hard-coded results do not replace formulas.'),('Bei B4=115 werden Ausgaben 205 € und Rest 0 € durch dieselben Formeln. Eingabeänderung und tatsächliche automatische Verknüpfung sind sichtbar zu machen.','Changing B4 to115 updates expenses to EUR205 and remainder to0 through the same formulas. Show the changed input and actual automatic links.'),('Das ursprüngliche Sparziel lässt 15 € Puffer, danach keinen. Variable Ausgaben oder Sparziel können begründet angepasst werden; Erwartungen sind keine Garantie und unerfasste Positionen können den Plan ändern.','The original saving goal leaves EUR15 slack, then none. Spending or saving may be reasonably adjusted; estimates are not guarantees and omitted items can change feasibility.'),('Beispiel B2=360,B3=170,B4=110,B5=180,B6=50; B7=B5/12, B8=SUM(B3:B4)+B7, B9=B2-B8-B6. Rücklage 15 €, Rest 15 €. Die Jahreszahlung wird nicht zusätzlich als volle Monatsausgabe doppelt gezählt.','For example B2=360,B3=170,B4=110,B5=180,B6=50; B7=B5/12, B8=SUM(B3:B4)+B7, B9=B2-B8-B6. Reserve EUR15, remainder EUR15. Do not also count the full annual bill as a monthly expense.'),('Bei B5=300 wird die Rücklage automatisch 25 € und der Rest 5 €. Die um 120 € höhere Jahresposition vermindert monatlichen Spielraum um 10 €, unter sonst gleichen Erwartungen.','At B5=300 the reserve automatically becomes EUR25 and remainder EUR5. The EUR120 annual increase reduces monthly room by EUR10, with other estimates fixed.'),('Monatsrücklage verteilt den erwarteten Jahresbedarf; sie ist nicht die tatsächliche Zahlung. Ohne Fälligkeit und Startbestand ist ausreichendes Geld am Termin nicht bewiesen. Bei frühem Termin kann trotz positivem Monatsrest eine Lücke bestehen.','A monthly reserve allocates annual expected needs; it is not the actual payment. Without due date and starting stock, liquidity at the date is unproven. An early due date can create a shortfall despite a positive monthly remainder.')],
[('K1: tatsächlich erzeugte Eingabetabelle; K2: verknüpfte richtige Summen-/Restformeln.','K1: actual input spreadsheet; K2: correctly linked sum/remainder formulas.'),('K1: ausgeführte Eingabeänderung; K2: automatische Werte fachlich erklärt.','K1: executed input change; K2: updated results explained.'),('K1: Tragfähigkeit/Sparziel; K2: bedingte Anpassung und Grenzen.','K1: feasibility/saving goal; K2: conditional adjustment and limits.'),('K1: eigene zweite Periodenplanung; K2: Jahres-/Monatsformel ohne Doppelzählung.','K1: own second period plan; K2: annual/monthly formula without double counting.'),('K1: tatsächlich verknüpfte 300-Änderung; K2: Rücklage/Rest erklärt.','K1: actual linked EUR300 change; K2: reserve/remainder explanation.'),('K1: Bestand/Fluss/Zahlung getrennt; K2: Fälligkeit und bestehende Reserve als Prüfangaben.','K1: stock/flow/payment distinction; K2: due date and existing reserve as needed facts.')],
('zeitlich konsistentes Budget mit Sparziel; tatsächlich erstellte verknüpfte Tabellenformeln und ausgeführte Eingabeänderung; Jahresrücklage ohne Doppelzählung und Unterscheidung von Zahlung/Liquidität','a period-consistent budget with a saving goal; actual linked spreadsheet formulas and an executed input change; annual reserve without double counting and distinction from payment/liquidity'))
add('6e138ab0','Eigene Empfehlungen schriftlich, medial und mündlich vermitteln','Communicate own recommendations in writing, media and speech',
('Fiktive Jugendgruppe: Ein defekter Lautsprecher kann laut vorläufigem Befund für 45 € repariert werden; ein gleich leistungsfähiger Ersatz kostet 110 €. Reparatur kann ein weiteres Jahr ermöglichen, Folgefehler sind unsicher. Verfügbares Budget 80 €. Gestalten Sie eigene schriftliche und medienunterstützte Ergebnisse und erläutern Sie diese tatsächlich mündlich in einer ausdrücklich benannten Unterrichts-/Rollen-/Aufnahmesimulation. Kein Kontakt zu echten Dritten; private Aufnahmen bleiben lokal. Rückfrage: „Garantiert die Reparatur ein Jahr?“','Fictional youth group: a faulty speaker can be repaired for EUR45 according to a provisional assessment; equal replacement costs EUR110. Repair may allow another year, but further faults are uncertain. Budget EUR80. Create original written and media-supported results and actually present them orally in an explicitly identified classroom/role/recording simulation. No real external contact; private recordings stay local. Follow-up: “Does repair guarantee a year?”'),
('Fiktive Leitung: Lieferant A kostet 18 € je Einheit und liefert verlässlich in zwei Tagen. B kostet 15 €, Lieferzeit ein bis acht Tage. Vierzig Einheiten werden in drei Tagen gebraucht; Lagerraum ist knapp, Ausfallwahrscheinlichkeiten fehlen. Erstellen Sie eigenständig eine schriftliche Entscheidungsvorlage und Vergleichsgrafik, tragen Sie sie tatsächlich mündlich in klar bezeichneter Leitungssimulation vor. Rückfrage: „Macht die Ersparnis B immer besser?“','Fictional management: supplier A costs EUR18 per unit and reliably delivers in two days. B costs EUR15 and takes one to eight days. Forty units are needed in three days; storage is limited and failure probabilities are unavailable. Create an original written brief and comparison graphic and actually deliver it orally in a clearly identified management simulation. Follow-up: “Does the saving always make B better?”'),
[('A1: Berechnen und begründen Sie die Handlungsempfehlung für die Jugendgruppe.','A1: Calculate and justify a recommendation for the youth group.'),('A2: Erstellen Sie eine eigene kurze schriftliche Empfehlung und eine passende medienunterstützte Darstellung.','A2: Create an original short written recommendation and suitable media-supported representation.'),('A3: Erläutern Sie das Ergebnis tatsächlich mündlich und beantworten Sie die Rückfrage; Folien oder Transkript allein ersetzen diesen Teil nicht.','A3: Actually explain the result orally and answer the follow-up; slides or a transcript alone do not replace this part.'),('B1: Berechnen Sie die Vergleichswerte und gewichten Sie Termin und Kosten bedingt.','B1: Calculate comparison values and conditionally weigh timing and cost.'),('B2: Erstellen Sie eine eigene Entscheidungsvorlage samt Grafik; verändern Sie Darstellung und Fachsprache zur Zielgruppe.','B2: Create an original brief and graphic; adapt representation and language to the audience.'),('B3: Tragen Sie tatsächlich mündlich vor, beantworten Sie den Einwand und benennen Sie Grenzen.','B3: Actually deliver the presentation orally, answer the objection and identify limits.')],
[('45 € statt 110 €, Differenz65 €; Reparatur passt in80 €, Ersatz nicht ohne weitere Finanzierung. Erwartete Nutzung und Folgerisiko begrenzen die Empfehlung.','EUR45 versus110, difference65; repair fits80, replacement requires more funding. Expected use and further-fault risk limit the recommendation.'),('Beispiel eigene Karte: „Reparatur zuerst prüfen: 45 € im Budget, mögliche weitere Nutzung, kein Garantiejahr“. Eine Balken-/Symbolgrafik zeigt Kosten/Budget und markiert Unsicherheit. Das Produkt muss tatsächlich erstellt sein, nicht nur vorgeschlagen.','For example an own card: “Consider repair first: EUR45 within budget, possible further use, no guaranteed year.” A bar/symbol graphic shows cost/budget and uncertainty. Actually create the product rather than only proposing it.'),('Ein tatsächlicher verständlicher mündlicher Vortrag verbindet Zahl und Bedingung; auf die Frage folgt „Nein, Befund und mögliche Folgefehler erlauben keine Garantie“. Aus einer simulierten Darbietung wird keine menschliche Erprobung behauptet.','Actual understandable oral delivery connects values and conditions; answer “No: the assessment and possible further faults do not guarantee a year.” Simulation is not claimed as human field testing.'),('A720 €, B600 €, Differenz120 €. A erfüllt die gegebene Frist; B kann sie erfüllen, garantiert sie aber nicht. Fehlende Wahrscheinlichkeiten verbieten erfundene Erwartungsverluste.','A EUR720, B600, difference120. A meets the stated deadline; B may meet it but does not guarantee it. Missing probabilities prohibit invented expected losses.'),('Eigene Leitungsvorlage trennt Kosten, Termin, Lagergrenze und offene Annahmen; Grafik vergleicht720/600 und Lieferfenster. Fachliche Sprache und priorisierte Option unterscheiden sich von der Jugendkarte; Alternativen wie eine begründete Teilbestellung sind bedingt zulässig.','An own management brief separates cost, timing, storage and assumptions; graphic compares720/600 and delivery windows. Language and priority differ from the youth card; justified partial-order alternatives are conditionally acceptable.'),('Die tatsächliche mündliche Erläuterung weist darauf hin, dass120 € nur der Einkaufsvorteil ist. Terminerfüllung, Prioritäten und fehlende Risikodaten verhindern „immer besser“. Eigene mündliche Leistung und Reaktion werden geprüft, keine echte Firmenfreigabe.','Actual oral delivery explains that EUR120 is only purchasing savings. Timing, priorities and missing risk data rule out “always better”. Assess own oral performance and response, not real company approval.')],
[('K1: richtige Kosten/Budget; K2: bedingte wirtschaftliche Gründe.','K1: correct cost/budget; K2: conditional economic reasons.'),('K1: tatsächliches eigenes Schriftprodukt; K2: tatsächliche konsistente passende Mediendarstellung.','K1: actual original written product; K2: actual consistent suitable media representation.'),('K1: tatsächliche mündliche Erläuterung; K2: fachliche Antwort ohne Garantie.','K1: actual oral explanation; K2: sound answer without guarantee.'),('K1: richtige Vergleichswerte; K2: Termin-/Unsicherheitsabwägung.','K1: correct comparison values; K2: timing/uncertainty reasoning.'),('K1: eigene schriftliche/mediale Vorlage; K2: erkennbare Anpassung für Leitung.','K1: own written/media brief; K2: evident adaptation for management.'),('K1: tatsächlicher Vortrag und Rückfrage; K2: wirtschaftliche Grenzen erklärt.','K1: actual delivery and follow-up; K2: economic limits explained.')],
('eigene wirtschaftliche Gründe und Bedingungen; tatsächlich eigene schriftliche Darstellung; tatsächlich eigene medienunterstützte Darstellung; tatsächliche mündliche Erläuterung mit Rückfrage; erkennbare Anpassung an unterschiedliche Adressaten','own economic reasons and conditions; an actual own written representation; an actual own media-supported representation; actual oral explanation with a follow-up; evident adaptation to different audiences'))
add('7179f558','Beteiligung: Zugang, Artikulation und Entscheidung unterscheiden','Participation: distinguish access, representation and decision',
('Im vollständig fiktiven Planspiel will der Gemeinderat am15.November2026 über einen Bustarif entscheiden. Bis10.November nimmt sein Sekretariat schriftliche Stellungnahmen und Beiträge eines offenen Onlineforums an. Eine Onlinepetition mit1200 Unterstützungen und ein Fahrgastverband mit begründeter Stellungnahme können in die Beratung gelangen; ausschließlich der Rat beschließt. Nicht alle Einwohner besitzen Internetzugang.','In a wholly fictional simulation a council decides bus fares on15November2026. Its office accepts written submissions and open online-forum contributions until10November. An online petition with1200 supporters and a passenger association’s reasoned submission can inform deliberation; only the council decides. Not all residents have internet access.'),
('Ein zweites fiktives Verfahren zu Arbeitsbedingungen endet mit Entscheidung eines benannten Modellparlaments am20.Dezember. Stellungnahmen von Gewerkschaft und Arbeitgeberverband sowie individuelle digitale Beiträge sind bis5.Dezember möglich. Verbände haben hauptamtliche Fachkräfte, einzelne Betroffene nur wenig Zeit; auch Briefbeiträge werden angenommen. Kein Beitrag erzeugt ein Vetorecht. Die Daten bilden kein reales Gesetzgebungsverfahren ab.','Another fictional procedure on working conditions ends with a model parliament’s decision on20December. Union/employer-association submissions and individual digital contributions are accepted until5December. Associations have professional staff; individuals have limited time. Letters are also accepted. No submission creates a veto. This is not an account of an actual legislative process.'),
[('A1: Ordnen Sie Petition und Verband nach Akteur, Zuständigkeit und Einflussweg ein.','A1: Classify petition and association by actor, authority and influence route.'),('A2: Vergleichen Sie digitalen und analogen Zugang mit konkreten Chancen und Hindernissen.','A2: Compare digital/offline access using specific opportunities and barriers.'),('A3: Prüfen Sie „1200 Unterstützungen entscheiden den Tarif“ und entwerfen Sie einen passenden nächsten Schritt.','A3: Assess “1200 supporters decide the fare” and design an appropriate next step.'),('B1: Ordnen Sie organisierte Stellungnahmen und Einzelbeiträge dem gegebenen Verfahren zu.','B1: Place organised submissions and individual contributions within the procedure.'),('B2: Beurteilen Sie Ressourcenunterschiede und eine mögliche Zugangshilfe.','B2: Assess resource differences and a possible access remedy.'),('B3: Trennen Sie Teilnahme und Durchsetzung; begründen Sie eine analoge und digitale Kombination ohne Erfolgsgarantie.','B3: Distinguish participation from success; justify an offline/digital combination without guarantees.')],
[('Petition bündelt Zustimmung/Reichweite; Verband bündelt begründete Interessen und Fachwissen. Beide adressieren Rat/Sekretariat innerhalb der Frist; der Einfluss läuft über Beratung, nicht eigene Beschlussmacht.','A petition aggregates support/reach; an association aggregates reasoned interests/expertise. Both address council/office within the deadline; influence works through deliberation, not their own decision power.'),('Onlinebeiträge können viele erreichen, schließen ohne Zugang aus. Verband und Brief ermöglichen andere Zugänge, benötigen Organisation/Zeit. Eine offene Anmeldung beseitigt Ressourcenunterschiede nicht automatisch.','Online contributions can reach many but exclude those without access. Associations and letters provide other routes and require organisation/time. Open admission does not automatically remove resource differences.'),('1200 ist ein Signal, kein im Modell geregelter bindender Beschluss. Eine fristgerechte begründete Stellungnahme mit Betroffenheit/Alternativen an das zuständige Organ passt; Ergebnisse bleiben offen.','1200 is a signal, not a binding decision under these rules. A timely reasoned submission about impacts/alternatives to the competent body is appropriate; outcomes remain open.'),('Verbände artikulieren organisierte Interessen; individuelle Beiträge bringen eigene Erfahrungen ein. Beide gehen bis5.Dezember an die Annahmestelle, die Entscheidung verbleibt am20.Dezember beim Modellparlament.','Associations express organised interests; individuals supply their experiences. Both submit by5December; the model parliament decides on20December.'),('Fachkräfte können Begründungen und Präsenz stärken. Verständliche Vorlagen, Briefe und erreichbare Beratung können Zeit-/Zugangshürden senken, garantieren aber keine gleiche Ressourcenausstattung oder gleiches Gewicht.','Professional staff can strengthen reasons and presence. Clear templates, letters and accessible advice can reduce time/access barriers without guaranteeing equal resources or weight.'),('Fristgerechter eigener Beitrag plus organisierte analoge Beratung kombiniert Sichtbarkeit und Bündelung. Teilnahme eröffnet Einflusswege; die Zahl oder Rechtsform eines Beitrags garantiert weder Zustimmung noch Veto.','A timely own submission plus organised offline consultation combines visibility and aggregation. Participation opens routes of influence; contribution count or form guarantees neither acceptance nor a veto.')],
[('K1: beide Akteure/Wege; K2: passende Zuständigkeit und Beratung.','K1: both actors/routes; K2: appropriate authority and deliberation.'),('K1: digitale Chancen/Grenzen; K2: analoge Zugänge mit Bedingungen.','K1: digital benefits/limits; K2: offline access with conditions.'),('K1: Artikulation versus Beschluss; K2: fristgerechter nächster Schritt.','K1: expression versus decision; K2: timely appropriate next step.'),('K1: organisierte/offene Wege; K2: Frist und Entscheidungsträger.','K1: organised/open routes; K2: deadline and decision-maker.'),('K1: konkrete Ressourcenwirkung; K2: begründete begrenzte Abhilfe.','K1: specific resource effect; K2: justified limited remedy.'),('K1: sinnvolle Kombination; K2: Einfluss-/Erfolgsgrenze.','K1: reasonable combination; K2: influence/success limit.')],
('analoge und digitale Interessenartikulation am konkreten Akteur/Zuständigkeitsweg; Zugang und Ressourcen mit Grenzen; Unterscheidung von Beteiligung und bindender Entscheidung','offline/digital interest representation by specific actor and authority; access and resources with limits; distinction between participation and binding decisions'))
add('ffe6ed04','Öffentlichkeit: Information, Kontrolle und Teilhabe prüfen','Public debate: examine information, scrutiny and participation',
('Eigener fiktiver Bericht R verlinkt ein offenes Gemeindedossier: Gesamtkosten steigen von100000 auf130000 €, ein neuer Leistungsumfang wird genannt und zwei Gegenpositionen werden begründet wiedergegeben. Beitrag S sagt nur „Kosten verdoppelt, alle Verantwortlichen unfähig“ und liefert keine Quelle; S hat viel mehr Aufrufe. Es liegen keine Reichweiten- oder Wirkungsdaten über demokratische Entscheidungen vor.','Original fictional report R links an open municipal dossier: costs rise from EUR100000 to130000, changed service is stated and two opposing positions are explained. S says only “Costs doubled; every official is incompetent”, without sources. S has far more views. No data establish effects on democratic decisions.'),
('Im zweiten eigenen Planspiel sortiert eine Plattform Beiträge zur Umgestaltung eines Marktplatzes nach erwarteter Aufmerksamkeit. Eine zugespitzte Forderung steht oben; ein quellengebundener Gegenbeitrag und die Position wenig digital erreichbarer Anwohner werden selten sichtbar. Der Mechanismus ist vorgegeben, repräsentative Meinungsdaten fehlen. Ein alternativ vorgeschlagenes Themenfenster macht Gegenpositionen mit Quellen sichtbar.','In another original simulation a platform ranks marketplace-renewal posts by predicted attention. A provocative demand ranks first; a sourced counterargument and digitally hard-to-reach residents are rarely visible. The mechanism is given; representative opinion data are missing. A proposed topic window would make sourced opposing positions visible.'),
[('A1: Prüfen Sie die Kostenbehauptung und Informationsfunktion beider Beiträge.','A1: Check the cost claim and information function of both contributions.'),('A2: Bewerten Sie öffentliche Kontrolle und erkennbare Perspektiven anhand des Quellenzugangs.','A2: Assess public scrutiny and visible perspectives using source access.'),('A3: Beurteilen Sie „Mehr Aufrufe beweisen bessere Demokratie“ anhand begründeter Kriterien.','A3: Assess “More views prove better democracy” using reasoned criteria.'),('B1: Erklären Sie Auswahl und Verstärkung im gegebenen Mechanismus.','B1: Explain selection and amplification in the stated mechanism.'),('B2: Bewerten Sie Teilhabe und Meinungsvielfalt; unterscheiden Sie Sichtbarkeit von Wahrheit.','B2: Assess participation and diversity; distinguish visibility from truth.'),('B3: Begründen Sie eine Abhilfe und ihre Grenzen für demokratische Willensbildung.','B3: Justify a remedy and its limits for democratic preference formation.')],
[('Anstieg30000 €, also30%, keine Verdopplung. R macht Daten/Umfang prüfbar; S erzeugt Aufmerksamkeit, aber keine prüfbare Begründung. Auch R kann durch Auswahl begrenzt sein.','Increase EUR30000, or30%, not doubling. R makes data/service checkable; S generates attention without checkable support. R can also be limited by selection.'),('Quellenzugang erlaubt Nachprüfung und Verantwortlichkeitsfragen. Zwei Gegenpositionen erweitern Perspektiven; weitere Betroffene oder Kontext können fehlen. Kontrolle ist eine Möglichkeit des Verfahrens, kein bewiesener Erfolg.','Source access permits verification and accountability questions. Two opposing positions broaden perspective; other people/context may be absent. Scrutiny is a procedural possibility, not an established success.'),('Reichweite misst Aufmerksamkeit, nicht Wahrheit oder Vielfalt. Demokratische Qualität benötigt prüfbare Informationen, Kritikzugang und zugängliche Auseinandersetzung; gewünschte politische Meinung ersetzt diese Kriterien nicht.','Reach measures attention, not truth or diversity. Democratic quality requires checkable information, access to criticism and accessible debate; preferred politics cannot replace these criteria.'),('Aufmerksamkeitsrang belohnt zugespitzte Beiträge und kann andere nach unten verdrängen. Das erklärt unterschiedliche Sichtbarkeit im Planspiel; es beweist keine allgemeine Kausalität für alle Plattformen.','Attention ranking rewards provocative contributions and can push others down. This explains visibility in the simulation, not universal causation for every platform.'),('Geringe Sichtbarkeit erschwert Kenntnis von Alternativen und Stimme einzelner Gruppen. Häufigkeit oben beweist keine korrekte Position; offene Zugänge allein sichern noch keine effektive Teilhabe.','Low visibility limits knowledge of alternatives and some groups’ voice. Ranking frequency does not establish correctness; formal openness alone does not ensure effective participation.'),('Quellengebundene Themenfenster, transparente Auswahl und analoge Ergänzung können Vielfalt/Zugang stärken. Moderation und begrenzte Aufmerksamkeit bleiben Probleme; ein bestimmtes Abstimmungsergebnis wird nicht garantiert.','Sourced topic windows, transparent selection and offline supplements can improve diversity/access. Moderation and limited attention remain problems; no particular vote is guaranteed.')],
[('K1: belegte Zahlenprüfung; K2: Informationsqualität beider Beiträge.','K1: evidenced number check; K2: information quality of both posts.'),('K1: konkrete Kontrolle; K2: Auswahl-/Perspektivgrenze.','K1: specific scrutiny function; K2: selection/perspective limit.'),('K1: Reichweite nicht Wahrheit; K2: demokratische Kriterienabwägung.','K1: reach is not truth; K2: democratic criteria reasoning.'),('K1: konkreter Mechanismus; K2: begrenzte Schlussweite.','K1: specific mechanism; K2: limited inference.'),('K1: Teilhabe/Vielfalt; K2: Sichtbarkeit versus Beleg.','K1: participation/diversity; K2: visibility versus evidence.'),('K1: passende Abhilfe; K2: begründete Grenzen.','K1: suitable remedy; K2: reasoned limits.')],
('Informationsfunktion anhand prüfbarer Quellen; öffentliche Kontrolle; Auswahl, Vielfalt und Teilhabemöglichkeiten mit begründeten demokratischen Chancen/Grenzen','information using verifiable sources; public scrutiny; selection, diversity and participation with reasoned democratic benefits/limits'))
add('bd9ec397','Journalistische Texte und Karikaturbeschreibungen wirtschaftspolitisch beurteilen','Assess journalism and cartoon descriptions on economic policy',
('Eigener fiktiver Kommentar: „Eine modellhafte Lohnuntergrenze steigt von12 auf14 € pro Stunde. Zwei Beschäftigte mit unverändert20 Wochenstunden erhalten jetzt je40 € mehr: Damit gewinnen alle, ohne Nachteil.“ Weitere Daten fehlen. Eigene Karikaturbeschreibung: Eine Lohnleiter führt zur Sonne; unten tragen kleine Betriebe die Leiter, einige Personen stehen neben ihr. Beschreibungen ersetzen hier keine behaupteten realen Presse- oder Bildquellen; es wird kein geltender Mindestlohn genannt.','Original fictional commentary: “A model wage floor rises from EUR12 to14 per hour. Two workers retaining20 weekly hours each receive EUR40 more: everyone therefore wins without any cost.” Other data are absent. Original cartoon description: a wage ladder reaches the sun; small firms support its base and some people stand beside it. These are not claimed real press/image sources or a current statutory minimum wage.'),
('Ein zweiter eigener fiktiver Kommentar fordert Abschaffung einer Modell-Umweltabgabe, weil ein Betrieb100 € mehr Kosten pro Woche berichtet. Keine Angaben zu Emissionen, Preisen oder Verwendung der Einnahmen. Eigene Karikaturbeschreibung: Ein rauchender Betrieb steht neben Wohnungen; eine Waage wiegt nur Betriebsgewinne, nicht den Rauch. Begründete unterschiedliche Deutungen sind zulässig.','Another original fictional commentary demands abolition of a model environmental levy because one firm reports EUR100 more weekly costs. No emissions, prices or revenue-use data are given. Original cartoon description: a smoking factory stands beside homes; a scale counts only profits, not smoke. Different reasoned interpretations are acceptable.'),
[('A1: Analysieren Sie Kernaussage, Rechenbeleg und unbelegte Verallgemeinerung des Textes.','A1: Analyse the text’s main claim, numerical support and unsupported generalisation.'),('A2: Deuten Sie Bildübertreibung und mögliche Interessen/Intention am konkreten Material.','A2: Interpret visual exaggeration and possible interests/intentions through the material.'),('A3: Nehmen Sie aus Sicht der Sozialen Marktwirtschaft ergebnisoffen Stellung.','A3: Give an open, reasoned assessment from the social-market-economy perspective.'),('B1: Prüfen Sie Textaussage und Beleggrenzen zur Umweltabgabe.','B1: Check the environmental-levy text and its evidence limits.'),('B2: Analysieren Sie die bildliche Pointe und was sie nicht beweist.','B2: Analyse the visual message and what it does not prove.'),('B3: Wägen Sie Freiheit, Effizienz, sozialen Ausgleich und relevante Umweltwirkungen mit fehlenden Daten ab.','B3: Weigh freedom, efficiency, social balance and relevant environmental effects with missing data.')],
[('2×20=40 € mehr Wochenlohn je Beschäftigtem bei unveränderter Zeit. Zwei Einzelbeobachtungen belegen nicht Gesamtwirkungen auf Arbeitszeit, Beschäftigung, Preise oder alle Einkommen. Kommentar und Werturteil bleiben erkennbar.','2×20=EUR40 more weekly pay per worker at unchanged hours. Two cases establish no aggregate effect on hours, employment, prices or all incomes. Commentary and judgement remain distinct.'),('Leiter/Sonne überhöhen die positive Lohnidee; tragende Betriebe können Kostenlasten zeigen, danebenstehende Personen Ausgeschlossene. Die Intention ist materialgestützt zu begründen, nicht zwingend eindeutig.','Ladder/sun exaggerate wage gains; supporting firms can represent burdens and people beside it exclusion. Interpret intentions through the material without requiring one definitive reading.'),('Schutz und Einkommen können sozialem Ausgleich dienen; unternehmerische Freiheit, Kosten und Effizienz verlangen Abwägung. Fehlende Wirkungsdaten verhindern „Gewinn für alle“ und eine vorgeschriebene Zustimmung/Ablehnung.','Protection/income can support social balance; firm freedom, costs and efficiency require weighing. Missing effects rule out “everyone wins” and any prescribed approval/rejection.'),('100 € sind ein einzelner privater Kostenbefund. Abschaffung folgt daraus nicht ohne Umweltkosten, Anreizwirkungen, Konkurrenz- und Verteilungsdaten. Eigene Interessen des Texts sind von Tatsachen zu trennen.','EUR100 is one private-cost observation. Abolition does not follow without environmental cost, incentives, competition and distribution data. Separate the commentary’s interests from facts.'),('Nicht gewogener Rauch verdeutlicht externe Belastungen und eine selektive Gewinnperspektive. Die Darstellung beweist weder genaue Schadenshöhe noch optimale Abgabe oder alle realen Firmenwirkungen.','Unweighed smoke highlights external burdens and a selective profit perspective. It establishes neither exact damage nor optimal levy nor all actual firm effects.'),('Ein bedingtes Urteil verbindet Freiheit/Handlungsspielraum, Effizienz durch mögliche Kosteninternalisierung, soziale Belastungsverteilung und Umweltwirkung. Erforderlich sind z.B.Emissionsreaktion und Ausgleichsverwendung; begründete andere Gewichtungen zählen.','A conditional judgement connects freedom/discretion, efficiency through possible internalisation, social burden distribution and environmental effects. Emissions response and compensation use are relevant missing facts; alternative justified weights count.')],
[('K1: Aussage und richtiger begrenzter Rechenbeleg; K2: Tatsache/Werturteil/Verallgemeinerung getrennt.','K1: claim and correct limited numerical support; K2: facts/judgement/generalisation separated.'),('K1: konkrete Bildmittel; K2: materialgebundene Intention/Interessen.','K1: specific visual devices; K2: material-based intentions/interests.'),('K1: sozialmarktwirtschaftliche Kriterien; K2: offenes evidenzgebundenes Urteil.','K1: social-market criteria; K2: open evidence-based judgement.'),('K1: selektiver Textbeleg; K2: fehlende Wirkung/Interessenprüfung.','K1: selective textual evidence; K2: missing effect/interest check.'),('K1: Externalitätenpointe; K2: Bild versus empirischer Beweis.','K1: externality message; K2: image versus empirical evidence.'),('K1: begründete Freiheit/Effizienz/Ausgleich/Umweltabwägung; K2: fallbezogene Daten- und Urteilsgrenzen.','K1: reasoned freedom/efficiency/balance/environment weighting; K2: case-based data/judgement limits.')],
('journalistische Kernaussage und Beleggrenzen; karikaturtypische Darstellung und Intention; begründete ergebnisoffene Einordnung anhand Freiheit, Effizienz, sozialem Ausgleich und relevanter Umweltwirkung','journalistic claim and evidence limits; cartoon-specific representation and intention; reasoned open assessment using freedom, efficiency, social balance and relevant environmental effects'))
add('b5762a90','Kulturmedien: ökonomische Mechanismen und Belegformen vergleichen','Cultural media: compare economic mechanisms and evidence forms',
('Drei eigene fiktive Miniaturen. Film-Drehbuch: schnelle Schnitte zeigen stets dieselbe Montagebewegung; am Ende lässt eine erschöpfte Figur ein Teil fallen. Literarischer Monolog: „Der zusätzliche Lohn bezahlt die Wohnung; zuhause schlafen die anderen schon, wenn ich komme.“ Sachbuchskizze: Produktivität sei Ausstoß je Arbeitsstunde; Modelltag1 hat60 Teile/6 Stunden, Modelltag2 hat80 Teile/8 Stunden. Keine reale Häufigkeitsstudie liegt vor.','Three original fictional miniatures. Film script: rapid cuts repeatedly show an assembly motion; an exhausted character drops a part. Literary monologue: “The extra pay covers rent; the others are asleep when I get home.” Nonfiction sketch: productivity is output per labour hour; model day1 has60 units/6 hours and day2 has80/8. No actual frequency study is supplied.'),
('Anderer Inhalt, drei eigene fiktive Miniaturen. Film-Drehbuch: Nahaufnahme eines Countdowns, dann Schnitt auf eine Warteschlange vor einem Modegeschäft. Literarischer Dialog: „Mitmachen kostet40 €, dann fehlt Geld für die Fahrt.“ — „Vielleicht gehöre ich sonst nicht dazu.“ Sachbuchskizze: Im Modellbudget60 € kostet das Kleidungsstück40 €, ein gewünschter Ausflug30 €; beide zusammen sind nicht bezahlbar. Opportunitätskosten beziehen sich auf die beste aufgegebene Alternative; welche das ist, hängt von Präferenzen ab.','Different content, three original fictional miniatures. Film script: close-up of a countdown followed by a queue outside a fashion shop. Literary dialogue: “Joining costs EUR40; then transport money is missing.” — “Perhaps I will not belong otherwise.” Nonfiction sketch: in a EUR60 model budget clothing costs40 and a desired outing30, so both are unaffordable. Opportunity cost concerns the best foregone alternative, which depends on preferences.'),
[('A1: Analysieren Sie ökonomischen Inhalt und filmische Gestaltung.','A1: Analyse economic content and film form.'),('A2: Analysieren Sie Lohn-/Zeitinteressen der Erzählstimme und die Produktivitätsaussage der Sachskizze.','A2: Analyse the narrator’s wage/time interests and the nonfiction productivity claim.'),('A3: Vergleichen Sie alle drei Beleg-/Darstellungsformen und begrenzen Sie reale Schlussfolgerungen.','A3: Compare all three evidence/representation forms and limit real-world inferences.'),('B1: Analysieren Sie Film und Dialog wirtschaftlich und in ihrer Gestaltung.','B1: Analyse film and dialogue economically and in their form.'),('B2: Werten Sie das Sachmodell aus; unterscheiden Sie Preis und Opportunitätskosten.','B2: Analyse the nonfiction model; distinguish price from opportunity cost.'),('B3: Vergleichen Sie alle drei Perspektiven und begründen Sie alternative Deutungen am Material.','B3: Compare all three perspectives and support alternative interpretations through the material.')],
[('Wiederholung kann Arbeitsteilung/standardisierte Schritte darstellen; schnelle Schnitte und Erschöpfung lenken die Sicht auf Belastung. Das Skript zeigt Inszenierung, nicht gemessene Produktivitätssteigerung oder allgemeine Arbeitsverhältnisse.','Repetition may represent division of labour/standardised steps; fast editing and exhaustion emphasise strain. The script is staging, not measured productivity growth or general labour conditions.'),('Die Innenstimme verbindet Lohnnutzen mit verlorener gemeinsamer Zeit, subjektiv und möglicherweise ambivalent.60/6=10 und80/8=10 Teile pro Stunde: größerer Tagesausstoß bedeutet hier keine höhere Stundenproduktivität.','The inner voice connects wage benefits with lost shared time, subjectively and possibly ambiguously.60/6=10 and80/8=10 units per hour: greater daily output does not mean higher hourly productivity here.'),('Film wirkt über Bild/Schnitt, Literatur über Innenperspektive, Sachskizze über Definition und transparente Modellzahlen. Keine Form belegt reale Häufigkeit/Kausalität; die Skizze erlaubt nur eine begrenzte Modellrechnung.','Film works through images/editing, literature through inner perspective, nonfiction through definitions and transparent model data. None establishes actual frequency/causation; the sketch supports limited model calculation.'),('Countdown/Warteschlange können Dringlichkeit oder sozialen Anreiz inszenieren. Der Dialog zeigt Knappheit und Zugehörigkeit aus subjektiver Stimme. Eine begründete Deutung folgt konkreten Mitteln, nicht einem unterstellten einheitlichen Zweck.','Countdown/queue may stage urgency or social incentives. The dialogue shows scarcity and belonging through subjective voice. Interpretation follows specific devices, not a presumed single purpose.'),('40+30=70>60, gemeinsame Wahl ist ausgeschlossen; Kleidung lässt20 €, Ausflug30 €. Der Preis40 € ist nicht automatisch der Wert der besten aufgegebenen Alternative; die Rangordnung muss begründet bzw.offenbleiben.','40+30=70>60, both cannot be chosen. Clothing leaves EUR20, outing30. Price40 is not automatically the value of the best foregone alternative; preferences must be justified or left open.'),('Inszenierung, Dialog und Modell eröffnen unterschiedliche Sicht auf Anreize/Knappheit. Der Film kann Kritik oder Ambivalenz zeigen; das Modell beweist keine tatsächliche Psyche. Deutung, erzählte Aussage und modellgestützte Behauptung bleiben getrennt.','Staging, dialogue and model offer different views of incentives/scarcity. Film can express criticism or ambiguity; the model establishes no actual psychology. Interpretation, narrative claim and model-supported assertion remain distinct.')],
[('K1: wirtschaftlicher Mechanismus; K2: filmische Mittel mit Grenze.','K1: economic mechanism; K2: film devices with limits.'),('K1: literarische Interessen/Innenperspektive; K2: sachliche Produktivitätsauswertung.','K1: literary interests/inner perspective; K2: nonfiction productivity analysis.'),('K1: alle drei Formen verglichen; K2: Interpretation/Modell/Empirie getrennt.','K1: all three forms compared; K2: interpretation/model/empirical evidence distinguished.'),('K1: Filmgestaltung und Anreiz; K2: Dialogperspektive und Knappheit.','K1: film form/incentive; K2: dialogue perspective/scarcity.'),('K1: konsistentes Budgetmodell; K2: Preis versus aufgegebene Alternative.','K1: consistent budget model; K2: price versus foregone alternative.'),('K1: begründeter Dreiformenvergleich; K2: alternative Deutung mit Erkenntnisgrenzen.','K1: reasoned three-form comparison; K2: alternative interpretation and epistemic limits.')],
('fallbezogene ökonomische Analyse; filmische Darstellung; literarische Sprecher-/Innenperspektive; Sachbuchdefinition/Modellbeleg; Vergleich aller drei Formen mit Trennung von Deutung und realer Empirie','case-based economic analysis; film representation; literary voice/inner perspective; nonfiction definition/model evidence; comparison of all three forms separating interpretation from actual empirical evidence'))
add('596c02e3','Wirtschaft-und-Recht-Projekt: tatsächlich auswerten und Methode revidieren','Economics-and-law project: execute analysis and revise method',
('Fiktiver Kiosk: TagA120 Verkäufe, TagB60; Einweg kostet0,25 € je Verkauf. Mehrweg kostet je Öffnungstag14 € feste Reinigung und0,05 € je Nutzung. Wählen Sie selbst zunächst einen Tag als ausdrücklich vorläufig repräsentativ, planen Sie eine Zwei-Tage-Kostenprognose und führen Sie sie aus. Danach sind beide Tagesmengen vollständig zu verwenden. Reale Nachfrage, Rückgaben und Umweltwirkungen wurden nicht beobachtet.','Fictional kiosk: dayA120 sales, dayB60; disposables cost EUR0.25 per sale. Reusables cost EUR14 cleaning per open day plus0.05 per use. First choose one day as explicitly provisional representative, plan and execute a two-day forecast. Then use both daily quantities in full. Actual demand, returns and environmental effects were not observed.'),
('Eigenes kleines Informationsprojekt für fiktive mangelhafte Kopfhörer. Ein anfänglicher behebbarer Mangel, gesetzlicher Nacherfüllungsanspruch und praktikable Reparatur werden für diese begrenzte Übung vorausgesetzt; keine unverhältnismäßigen Reparaturkosten sind gegeben. Eigene Normhilfe nach tatsächlicher amtlicher Lektüre am10.Oktober2026, §439BGB(1),(4),(5): Käufer wählen grundsätzlich Mangelbeseitigung oder mangelfreie Lieferung; bei unverhältnismäßigen Kosten bestehen gesetzliche Verweigerungsgrenzen, die u.a.mangelfreien Wert, Mangelbedeutung und erhebliche Nachteile der anderen Abhilfe berücksichtigen; die Sache ist zur Nacherfüllung bereitzustellen. Diese Hilfe behandelt keine umfassende Rücktritts-/Rückzahlungsprüfung. Primärquelle: https://www.gesetze-im-internet.de/bgb/__439.html . Eigenes fiktives Protokoll: Auf eine von Ihnen formulierte allgemeine Ja/Nein-Verständlichkeitsfrage antworten A und B „Ja“. A fordert automatisch sofort Geld zurück; B fordert Reparatur und bietet die Kopfhörer zur Prüfung an.','Own small information project on fictional defective headphones. An initial repairable defect, statutory entitlement to cure and feasible repair are assumed in this limited exercise; no disproportionate repair costs are supplied. Own reading aid after actual official reading on10October2026, BGB439(1),(4),(5): buyers normally choose repair or defect-free replacement; disproportionate costs can justify statutory refusal, considering defect-free value, significance of the defect and serious disadvantages of the alternative cure. The item must be made available for cure. This aid is not a full rescission/refund analysis. Primary source: https://www.gesetze-im-internet.de/bgb/__439.html . Own fictional log: A and B say “Yes” to your selected general yes/no comprehension question. A demands an automatic immediate refund; B requests repair and offers the headphones for inspection.'),
[('A1: Schreiben Sie einen abgegrenzten Projektplan, wählen Sie den ersten Auswertungsschritt begründet und führen Sie die Prognose aus.','A1: Write a bounded project plan, justify the initial analytical step and execute the forecast.'),('A2: Prüfen und ändern Sie den Arbeitsweg; berechnen Sie beide Tage tatsächlich getrennt und aggregieren Sie.','A2: Test and revise the procedure; actually calculate days separately and aggregate.'),('A3: Vergleichen Sie erste und revidierte Ergebnisse in einem eigenen Entscheidungsbericht; erläutern Sie Methodenwirkung und Grenzen.','A3: Compare initial/revised results in an own decision report; explain the method’s effect and limits.'),('B1: Planen und erstellen Sie tatsächlich eine Informationskarte samt Musteranfrage und eine eigene anfängliche Ja/Nein-Prüffrage.','B1: Plan and actually create an information card, model request and own initial yes/no test question.'),('B2: Revidieren Sie die Prüfmethode zu eigenen Fallfragen und einem fachlichen Raster; wenden Sie es tatsächlich auf A und B an.','B2: Revise the test into own case questions and a subject-based rubric; actually apply it to A and B.'),('B3: Vergleichen Sie beide Auswertungen, begründen Sie die Methodenänderung und bewerten Sie Produkt und Vorgehen gegenüber der Ausgangsfrage.','B3: Compare both evaluations, justify the changed method and evaluate product/procedure against the original question.')],
[('Ein eigener Plan benennt Frage, Daten, Rechnung und Bericht. TagA als Vertreter: Einweg60 €, Mehrweg40 € für zwei Tage; TagB:30/34 €. Die frei gewählte Erstannahme wird offengelegt und wirklich ausgerechnet, nicht nur erwähnt.','An own plan states question, data, calculation and report. ExtrapolatingA: disposables EUR60, reusables40 for two days; extrapolatingB:30/34. Disclose and actually calculate the freely chosen initial assumption.'),('Vollständige Tagesrechnung: A30/20 €, B15/17 €; Summen45/37 €. Die geänderte Aggregation berücksichtigt unterschiedliche Mengen und zweimal feste Reinigung. Der gewählte erste und geänderte Schritt werden dokumentiert.','Complete day calculations: A EUR30/20, B15/17; totals45/37. Revised aggregation handles different volumes and cleaning twice. Document the chosen initial and revised step.'),('Im gegebenen vollständigen Geldkostenmodell ist Mehrweg8 € günstiger. ErstannahmeA ergab20 €, B dagegen4 € Mehrwegmehrkosten. Der Bericht erklärt, warum Tageswahl das Ergebnis verfälscht und vollständige Aggregation es korrigiert. Umweltwirkung/Rückgabe/Demand bleiben offen; es fand kein Schulversuch statt.','In the complete monetary model reusables are EUR8 cheaper. InitialA suggested20 savings; initialB4 extra reusable cost. Explain why day selection distorts results and aggregation corrects it. Environment/returns/demand remain unknown; no school trial occurred.'),('Eine eigene Karte erklärt bedingte Reparatur-/Ersatzwahl, gesetzliche Grenzen und Bereitstellung; Musteranfrage verlangt Reparatur und bietet die Sache an. Eigene erste Frage z.B.„Ist die Karte verständlich?“ erfasst nach dem gelieferten Protokoll zweimalJa. Tatsächliche eigene Produkte sind vorzulegen.','An own card explains conditional repair/replacement choice, statutory limits and availability; the model request seeks repair and offers the item. An initial question such as “Is this card clear?” yields twoYes answers in the log. Submit actual own products.'),('Eigene Prüffragen verlangen konkrete Abhilfe und Bereitstellung. Ein Raster kann dafür je ein begründetes Merkmal verwenden: A zeigt aus der Normhilfe keine automatische Rückzahlung, B passende Reparatur/Bereitstellung. Das eigene Raster wird mit ausgewiesenen Befunden wirklich auf beide angewandt.','Own questions request a specific remedy and availability. A rubric can use one justified feature for each: the aid supports no automatic refund forA, whileB demonstrates appropriate repair/availability. Actually apply the own rubric to both with explicit findings.'),('Ja/Ja bescheinigt nur Selbstauskunft, das geänderte Raster trennt A/B fachlich. Methodenänderung, tatsächliche Anwendung und Ergebnisvergleich werden begründet; bloße Kartenkorrektur genügt nicht. Kleiner fiktiver Datensatz und begrenzte Normhilfe erlauben keine Vollbeherrschung oder reale Befragungsaussage.','Yes/Yes is self-report only; the revised rubric distinguishesA/B substantively. Explain changed method, actual application and outcome comparison; merely editing the card is insufficient. Small fictional data and limited legal aid support no full-mastery or real-survey claim.')],
[('K1: eigener begründeter Projektplan; K2: tatsächlich ausgeführte gewählte Erstprognose.','K1: own reasoned project plan; K2: actually executed selected initial forecast.'),('K1: tatsächliche vollständige Tages-/Summenrechnung; K2: dokumentierte Methodenrevision.','K1: actual complete day/total calculation; K2: documented method revision.'),('K1: Ergebnisvergleich und fachlicher Bericht; K2: Methodenwirkung und Grenzen.','K1: outcome comparison/report; K2: method’s effect/limits.'),('K1: eigene Karte/Anfrage/Erstfrage; K2: fachlich begrenzte Normdarstellung.','K1: own card/request/initial question; K2: bounded accurate legal explanation.'),('K1: eigene begründete neue Prüfmethode; K2: tatsächlich angewendeter A/B-Befund.','K1: own reasoned new testing method; K2: actually appliedA/B findings.'),('K1: ausgeführter Methoden-/Ergebnisvergleich; K2: Auswertung gegenüber Frage mit Grenzen.','K1: executed method/outcome comparison; K2: evaluation against the question with limits.')],
('eigenständig begründeter Projektplan; tatsächlich erarbeitete fachliche Arbeitsprodukte/Rechnungen; tatsächliche begründete Änderung eines gewählten Auswertungsschritts mit erneut ausgeführter Anwendung; Vergleich der Ergebnisse und fachliche Auswertung mit Grenzen','an own justified project plan; actually produced subject-based products/calculations; a justified actual change to a selected analysis step with re-executed application; outcome comparison and subject-based evaluation with limits'))
add('72f45efc','VWL und BWL: denselben Fall nach Untersuchungsfokus einordnen','Economics and business administration: classify one case by focus',
('Fiktive Bäckerei: Mehl wird teurer. A fragt, welche Einkaufsmenge, Produktionsplanung und Finanzierung zu ihren betrieblichen Zielen passen. B fragt nach Brotmarktangebot und Nachfrage. C untersucht, wie ein einzelner Haushalt sein knapperes Budget auf Brot und andere Güter verteilt, um allgemeine Entscheidungsbedingungen zu erklären. Alle verwenden dieselben Daten.','Fictional bakery: flour becomes more expensive. A asks which purchasing quantity, production plan and finance fit its business objectives. B asks about supply/demand in the bread market. C studies one household’s allocation of a tighter budget between bread/other goods to explain general decision conditions. All use the same data.'),
('Fiktiver Busbetrieb: A prüft seine Tarifgestaltung und Personalplanung im Hinblick auf den eigenen Betrieb. B untersucht, wie günstigere Tickets mit kommunalem Zuschuss Verkehrsmittelwahl und Verteilung öffentlicher Mittel verändern können. C betrachtet die Nachfrageentscheidung einer einzelnen Person als mikroökonomischen Fall. Es sind Fragestellungen, keine bewiesenen Wirkungen.','Fictional bus company: A studies fares/staffing for its own operations. B asks how cheaper subsidised tickets may affect transport choice and public resource allocation. C treats one person’s demand choice as a microeconomic case. These are questions, not established effects.'),
[('A1: Ordnen Sie die betriebliche und Marktfrage begründet zu.','A1: Justifiably classify the firm and market questions.'),('A2: Erklären Sie die Haushaltsfrage und prüfen Sie „Ein Akteur bedeutet BWL“.','A2: Explain the household question and assess “One actor means business administration”.'),('A3: Zeigen Sie, wie derselbe Mehlpreisfall beide Perspektiven trägt.','A3: Show how the same flour-price situation supports both perspectives.'),('B1: Ordnen Sie die Betriebs- und Allokationsfrage nach Fokus ein.','B1: Classify operations and allocation questions by focus.'),('B2: Begründen Sie die mikroökonomische Einzelpersonenfrage und Grenzen der Zuordnung.','B2: Justify the individual microeconomic question and limits of classification.'),('B3: Prüfen Sie „Unternehmensdaten machen jede Untersuchung zur BWL“; formulieren Sie eine passende Frage jeder Perspektive.','B3: Assess “Company data makes every study business administration”; formulate an appropriate question for each perspective.')],
[('A ist BWL wegen betrieblicher Steuerung; B VWL wegen Marktbeziehungen. Zuordnung folgt dem Untersuchungsgegenstand, nicht Branche oder Größe.','A is business administration because it concerns managing the firm; B economics because it concerns market relationships. Focus, not industry or size, determines classification.'),('C kann VWL/Mikroökonomie sein: Erklärung von Haushaltswahl unter ökonomischen Bedingungen. VWL enthält Mikro- und Makroökonomie; Anzahl dargestellter Akteure entscheidet nicht.','C can be economics/microeconomics: explaining household choice under economic conditions. Economics includes micro/macro; actor count does not decide classification.'),('Die Bäckerei optimiert eigene Prozesse; die VWL untersucht Preisbeziehungen/Entscheidungen. Gleiche Mehlpreise und Daten liefern unterschiedliche Fragen; Schnittmengen können begründet bestehen.','The bakery manages its processes while economics studies price relationships/choices. Equal flour prices/data support different questions; justified overlaps can exist.'),('A ist BWL, B VWL, weil B Anreize und knappe öffentliche Mittel über die eigene Betriebssteuerung hinaus untersucht. Günstigere Tickets sind zunächst eine zu prüfende Ursache, kein Ergebnis.','A is business administration, B economics because it studies incentives/public scarcity beyond managing the company. Cheaper tickets are a proposed influence, not an established outcome.'),('C erklärt allgemeine Nachfragebedingungen an einem Fall und kann Mikroökonomie sein. Eine Frage nur zur individuellen Verwaltung eines Unternehmens wäre anders fokussiert. Methoden und Daten allein reichen für keine Einordnung.','C explains general demand conditions through one case and can be microeconomics. Managing an individual firm would have a different focus. Tools/data alone do not determine classification.'),('Falsch: Datenquelle entscheidet nicht. Beispielsweise BWL„Welche Personal-/Tarifplanung erfüllt unsere Ziele?“, VWL„Wie beeinflussen Tickets die Nachfrage und Ressourcenzuteilung?“. Beide können denselben Datensatz verwenden.','False: data source does not decide. For example business administration: “Which staffing/fares fit our objectives?” Economics: “How do fares affect demand/resource allocation?” Both can use the same dataset.')],
[('K1: A/B korrekt nach Fokus; K2: fallbezogene Begründung.','K1: correctA/B classification by focus; K2: case-based justification.'),('K1: Haushaltsfrage mikroökonomisch; K2: Akteurszahlverwechslung begründet aufgelöst.','K1: household question as microeconomics; K2: actor-count misconception resolved.'),('K1: derselbe Sachverhalt in zwei Perspektiven; K2: begründete Verbindung/Unterscheidung.','K1: same subject in two perspectives; K2: reasoned connection/distinction.'),('K1: Betriebsfokus; K2: Anreiz-/Allokationsfokus.','K1: firm-management focus; K2: incentive/allocation focus.'),('K1: Einzelperson versus allgemeine ökonomische Frage; K2: Zuordnungsgrenze.','K1: individual versus general economic question; K2: classification limit.'),('K1: Datenquelle nicht entscheidend; K2: tatsächlich eigene passende zwei Fragen.','K1: data source is not decisive; K2: two own appropriate questions.')],
('BWL-/VWL-Zuordnung anhand konkreten Untersuchungsfokus; Mikroökonomie trotz einzelner Akteure; begründete Erklärung zweier Perspektiven am selben Sachverhalt/Datenbestand','business-administration/economics classification by specific investigative focus; microeconomics despite individual actors; a reasoned explanation of two perspectives on the same subject/dataset'))
add('f478f85e','Wirtschaftswissenschaft: Gegenstand, Werkzeug und Nachbardisziplinen','Economics: subject, tools and neighbouring disciplines',
('Eine fiktive Stadt prüft günstigere Bustickets. Eine Gruppe untersucht Nachfrage, Budget und Anreize; eine andere erklärt Verkehrsgewohnheiten, eine dritte untersucht ungleichen Zugang und eine vierte misst technische Emissionen. Rechenmodelle und Befragungsdaten stehen allen offen. Die Gruppenfragen sind vorgegeben, Ergebnisse noch nicht.','A fictional city considers cheaper bus tickets. One group studies demand, budgets/incentives; another transport habits; a third unequal access; a fourth technical emissions. Mathematical models and survey data are available to all. Questions, not results, are supplied.'),
('Fiktives Reparaturprojekt: Ökonomische Gruppe untersucht, wie Preise, Einkommen und Anreize Haushaltsentscheidungen zu Reparatur oder Ersatz prägen. Technische Gruppe misst Reparierbarkeit; eine psychologische Gruppe untersucht Gewohnheit und Bezugspunkte. Eine Person sagt: „Rechenmodelle machen die Untersuchung zur Mathematik, Geräte zum naturwissenschaftlichen Fach.“','Fictional repair project: an economics group studies how prices, income/incentives shape repair/replacement choices. Engineers measure repairability; psychologists study habits/reference points. Someone says: “Mathematical models make the study mathematics; devices make it natural science.”'),
[('A1: Ordnen Sie die Wirtschaftswissenschaft anhand ihres Gegenstands in das Wissenschaftssystem ein.','A1: Place economics within the sciences by its subject.'),('A2: Erläutern Sie zwei passende Beiträge benachbarter Disziplinen zum konkreten Fall.','A2: Explain two suitable neighbouring contributions to this case.'),('A3: Trennen Sie Fragestellung, Rechenwerkzeug und technische Datenquelle.','A3: Distinguish question, mathematical tool and technical data source.'),('B1: Begründen Sie die ökonomische Einordnung im neuen Reparaturkontext.','B1: Justify economic classification in the new repair setting.'),('B2: Verknüpfen Sie technische und psychologische Beiträge mit der ökonomischen Frage, ohne sie gleichzusetzen.','B2: Connect engineering/psychology to the economic question without equating them.'),('B3: Prüfen Sie die beiden Fachbehauptungen und nennen Sie die Rolle begründeter Modellannahmen.','B3: Assess both disciplinary claims and explain justified model assumptions.')],
[('Wirtschaftswissenschaft untersucht wirtschaftliches Handeln von Menschen/Institutionen mit knappen Mitteln und wird hier sozialwissenschaftlich eingeordnet. Entscheidend sind Entscheidungen, Anreize und Ressourcen, nicht das benutzte Gerät.','Economics studies economic behaviour by people/institutions under scarcity and is classified here as social science. Decisions, incentives and resources matter, not the device used.'),('Psychologie kann Gewohnheiten erklären, Soziologie soziale Zugänge, technische Wissenschaften Emissionen messen. Zwei begründet gewählte Beiträge liefern relevante Daten/Erklärungen, ersetzen aber keine Budget-/Nachfragefrage.','Psychology can explain habits, sociology access, and engineering measure emissions. Two reasoned contributions supply relevant data/explanations without replacing budget/demand questions.'),('Die ökonomische Frage erklärt Anreize/Nachfrage. Mathematik modelliert Beziehungen; Emissionsmessung beschreibt technische Bedingungen. Befragungsdaten sind Daten, nicht selbst die Disziplin; Annahmen bestimmen zulässige Schlüsse.','The economic question explains incentives/demand. Mathematics models relationships; emission measurement describes technical conditions. Surveys are data, not the discipline itself; assumptions limit inferences.'),('Haushaltswahl über Preise/Einkommen ist wirtschaftliches Handeln. Deshalb bleibt es eine sozialwissenschaftlich-ökonomische Untersuchung, obwohl materielle Geräte und Technik vorkommen.','Household choice under prices/income is economic behaviour, so the study remains economic/social-scientific despite material devices and technology.'),('Reparierbarkeit begrenzt Handlungsoptionen; Psychologie kann Gewohnheit/Referenzwirkungen prüfen. Ökonomie verbindet solche Beiträge mit knappen Mitteln und Anreizen. Keine Disziplin liefert allein automatisch die ganze Erklärung.','Repairability limits feasible options; psychology can examine habits/reference effects. Economics connects these to scarcity/incentives. No one discipline automatically supplies the whole explanation.'),('Beide pauschalen Zuordnungen sind falsch: Gegenstand/Frage, nicht Werkzeug/Kontext, entscheidet. Modellannahmen zu Preisen, Möglichkeiten und Präferenzen sowie prüfbare Daten machen den Beitrag transparent; ohne Ergebnisdaten ist keine reale Kausalwirkung bewiesen.','Both blanket classifications are false: subject/question, not tool/context, is decisive. Assumptions about prices, options/preferences and checkable data make contributions transparent; without outcomes no actual causal effect is established.')],
[('K1: wirtschaftlicher Gegenstand; K2: sozialwissenschaftliche Einordnung begründet.','K1: economic subject; K2: justified social-science classification.'),('K1: erster passender Nachbarbeitrag; K2: zweiter Beitrag und wirtschaftliche Verbindung.','K1: first appropriate neighbouring contribution; K2: second and economic connection.'),('K1: Werkzeug/Daten/Frage getrennt; K2: begründete Rolle und Grenzen.','K1: tool/data/question separated; K2: reasoned role and limits.'),('K1: konkrete Wirtschaftsfrage; K2: begründete Einordnung trotz Technik.','K1: specific economic question; K2: justified classification despite technology.'),('K1: technische/psychologische Beiträge; K2: Verbindung ohne Gleichsetzung.','K1: engineering/psychology contributions; K2: connection without equivalence.'),('K1: beide Werkzeug-/Kontextverwechslungen geprüft; K2: Annahmen-/Datenrolle.','K1: both tool/context confusions examined; K2: assumptions/data role.')],
('begründete sozialwissenschaftliche Einordnung anhand wirtschaftlichen Handelns; konkrete relevante Beiträge benachbarter Disziplinen; Unterscheidung des Gegenstands von Werkzeug und technischen Kontextdaten','justified social-science classification by economic behaviour; specific relevant neighbouring contributions; distinction between subject and tools/technical context data'))
